def moving_average(nums, window_size):
    if window_size <= 0:
        raise ValueError("Window size must be a positive integer.")
    if len(nums) < window_size:
        raise ValueError("Window size cannot be greater than the number of elements in the list.")

    cumulative_sum = 0
    sum_values = []

    for i in range(len(nums)):
        cumulative_sum += nums[i]
        if i >= window_size:
